package com.nexusdrive.auth.controller;import com.nexusdrive.auth.dto.*;import com.nexusdrive.auth.service.*;import com.nexusdrive.common.dto.ApiResponse;import io.swagger.v3.oas.annotations.Operation;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;private final LoginRateLimiter limiter;public AuthController(AuthService a,LoginRateLimiter l){auth=a;limiter=l;}@Operation(summary="Register an account")@PostMapping("/register")@ResponseStatus(HttpStatus.CREATED) public ApiResponse<AuthResponse> register(@Valid @RequestBody RegisterRequest r){return ApiResponse.ok(auth.register(r));}@Operation(summary="Authenticate and issue tokens")@PostMapping("/login")public ApiResponse<AuthResponse> login(@Valid @RequestBody LoginRequest r,HttpServletRequest req){limiter.check(req.getRemoteAddr()+":"+r.username().toLowerCase());return ApiResponse.ok(auth.login(r));}@Operation(summary="Rotate a refresh token")@PostMapping("/refresh")public ApiResponse<AuthResponse> refresh(@Valid @RequestBody TokenRequest r){return ApiResponse.ok(auth.refresh(r.refreshToken()));}@Operation(summary="Revoke a refresh token")@PostMapping("/revoke")public ApiResponse<Void> revoke(@Valid @RequestBody TokenRequest r){auth.revoke(r.refreshToken());return ApiResponse.ok(null,"Revoked");}}
